  private Polygon2D(
      final double minX,
      final double maxX,
      final double minY,
      final double maxY,
      double[] x,
      double[] y,
      Component2D holes) {
    this.minY = minY;
    this.maxY = maxY;
    this.minX = minX;
    this.maxX = maxX;
    this.holes = holes;
    this.tree = EdgeTree.createTree(x, y);
  }

  private Polygon2D(XYPolygon polygon, Component2D holes) {
    this(
        polygon.minX,
        polygon.maxX,
        polygon.minY,
        polygon.maxY,
        XYEncodingUtils.floatArrayToDoubleArray(polygon.getPolyX()),
        XYEncodingUtils.floatArrayToDoubleArray(polygon.getPolyY()),
        holes);
  }

  private Polygon2D(Polygon polygon, Component2D holes) {
    this(
        polygon.minLon,
        polygon.maxLon,
        polygon.minLat,
        polygon.maxLat,
        polygon.getPolyLons(),
        polygon.getPolyLats(),
