  final double decodedLat = lat * LAT_DECODE;
  final double decodedLon = lon * LON_DECODE;
  assert decodedLat >= MIN_LAT_INCL;
  assert decodedLat < MAX_LAT_INCL;
  assert decodedLon >= MIN_LON_INCL;
  assert decodedLon < MAX_LON_INCL;
  if (tree instanceof Polygon2D) {
    final Polygon2D polygon = (Polygon2D) tree;
    final double minX = polygon.getMinX();
    final double maxX = polygon.getMaxX();
    final double minY = polygon.getMinY();
    final double maxY = polygon.getMaxY();
    final double latFromMin = decodedLat - minY;
    final double lonFromMin = decodedLon - minX;
    final double latFromMax = maxY - decodedLat;
    final double lonFromMax = maxX - decodedLon;
    final boolean insideMinX = lonFromMin >= 0;
    final boolean insideMaxX = lonFromMax >= 0;
    final boolean insideMinY = latFromMin >= 0;
    final boolean insideMaxY = latFromMax >= 0;
    if (insideMinX
        && insideMaxX
        && insideMinY
        && insideMaxY) {
      final EdgeTree root = polygon.tree;
      EdgeTree[] pending = new EdgeTree[16];
      int pendingCount = 0;
      pending[pendingCount++] = root;
      byte winding = 0;
      boolean onEdge = false;
      while (pendingCount > 0 && onEdge == false) {
        final EdgeTree node = pending[--pendingCount];
        final double nodeX1 = node.x1;
        final double nodeY1 = node.y1;
        final double nodeX2 = node.x2;
        final double nodeY2 = node.y2;
        final double nodeLow = node.low;
        final double nodeMax = node.max;
        final EdgeTree nodeLeft = node.left;
        final EdgeTree nodeRight = node.right;
        final double edgeDx = nodeX2 - nodeX1;
        final double edgeDy = nodeY2 - nodeY1;
        final double latFromY1 = decodedLat - nodeY1;
        final double lonFromX1 = decodedLon - nodeX1;
        final double latFromY2 = decodedLat - nodeY2;
        final double lonFromX2 = decodedLon - nodeX2;
        if (decodedLat <= nodeMax) {
          final boolean yOnFlatEdge = latFromY1 == 0 && latFromY2 == 0;
          final boolean yBetweenDown = latFromY1 <= 0 && latFromY2 >= 0;
          final boolean yBetweenUp = latFromY1 >= 0 && latFromY2 <= 0;
          if (yOnFlatEdge || yBetweenDown != yBetweenUp) {
            final boolean xOnFlatEdge = lonFromX1 == 0 && lonFromX2 == 0;
            final boolean xBetweenLeft = lonFromX1 <= 0 && lonFromX2 >= 0;
            final boolean xBetweenRight = lonFromX1 >= 0 && lonFromX2 <= 0;
            final int orientation =
                GeoUtils.orient(
                    nodeX1,
                    nodeY1,
                    nodeX2,
                    nodeY2,
                    decodedLon,
                    decodedLat);
            if (xOnFlatEdge || (xBetweenLeft != xBetweenRight && orientation == 0)) {
              onEdge = true;
            } else if ((latFromY1 < 0) != (latFromY2 < 0)) {
              final double slopeTerm = edgeDx * latFromY1;
              final double xIntersect = slopeTerm / edgeDy + nodeX1;
              final double lonDeltaToEdge = decodedLon - xIntersect;
              if (lonDeltaToEdge < 0) {
                winding ^= 0x01;
              }
            }
          }
          if (onEdge == false && nodeLeft != null) {
            if (pendingCount == pending.length) {
              final int grownSize = pending.length << 1;
              EdgeTree[] grown = new EdgeTree[grownSize];
              System.arraycopy(
                  pending,
                  0,
                  grown,
                  0,
                  pending.length);
              pending = grown;
            }
            pending[pendingCount++] = nodeLeft;
          }
          if (onEdge == false && nodeRight != null && decodedLat >= nodeLow) {
            if (pendingCount == pending.length) {
              final int grownSize = pending.length << 1;
              EdgeTree[] grown = new EdgeTree[grownSize];
              System.arraycopy(
                  pending,
                  0,
                  grown,
                  0,
                  pending.length);
              pending = grown;
            }
            pending[pendingCount++] = nodeRight;
          }
